def clen(t): return len(re.sub(r'\\x[0-9A-F]{2}','x',t))
out=[]
for name,tab in (("1",SMK),("0",FM1)):
    out.append(f"#if LEARN_UI_SMK" if name=="1" else "#else")
    for page in (1,2,3,4):
        rows=[]
        for sc in tab[page]:
            assert len(sc)<=13,(page,sc[0],len(sc))
            for t in sc: assert clen(t)<=29,(t,clen(t))
            items=[]
            for t in sc:
                c='"'+t+'"'
                c=re.sub(r'(\\x[0-9A-F]{2})([0-9A-Fa-f])',r'\1" "\2',c)
                items.append(c)
            rows.append("    {"+", ".join(items)+", 0}")
        out.append(f"static const char *const HELP{page}[HELP_SCREENS][14] = {{\n"+",\n".join(rows)+"};")
out.append("#endif")
src=open('learn/main.c').read()
a=src.index("/* the help: f") if "/* the help: f" in src else src.index("/* the help: three")
b=src.index('static void overlay_help(void)')
hdr='''/* the help: four screens a page (what it is for and how to learn here; the buttons; the knobs and faders; what the
 * screen shows), in the names printed on the panel in the player's hands. Generated and checked (every line fits:
 * 29 characters; 12 lines a screen) by tools/help_tables.py. */
'''
src=src[:a]+hdr+"\n".join(out)+"\n"+src[b:]
open('learn/main.c','w').write(src)
print("ok")
